def analyze_9_regions(r):
    """Find all 9-regions and gaps in a row"""
    nine_positions = [c for c, v in enumerate(r) if v == 9]
    if not nine_positions:
        return [], "no 9s"

    regions = []
    current_start = nine_positions[0]
    current_end = current_start

    for pos in nine_positions[1:]:
        if pos == current_end + 1:
            # continue same region
            current_end = pos
        else:
            # gap found
            regions.append((current_start, current_end))
            current_start = pos
            current_end = pos

    regions.append((current_start, current_end))

    return regions, nine_positions

