program_code = '''
def transform(grid):
    result = []
    for row in grid:
        # Find rightmost 4 (background)
        last_bg = None
        first_bg = None
        for i in range(len(row) - 1, -1, -1):
            if row[i] == 4:
                last_bg = i
                break

        for i in range(len(row)):
            if row[i] == 4:
                first_bg = i
                break

        if last_bg is None or first_bg is None:
            # No background pixels, keep row unchanged
            result.append(row[:])
        else:
            # Check if uniforms from first_bg to last_bg
            is_uniform = all(row[i] == 4 for i in range(first_bg, last_bg))
            if is_uniform:
                # Apply alternating pattern 1,4,1,4,... keeping last as 4
                new_row = row[:]
                for i in range(first_bg, last_bg):
                    new_row[i] = 1 if (last_bg - i) % 2 == 1 else 4
                result.append(new_row)
            else:
                # Not uniform, keep row unchanged
                result.append(row[:])
    return result
'''

